"""Drop config.yml entries that autogenerated.yml already sets to the same value.

config.yml loads last, so a stale copy would pin the value against later repo changes.
Usage: prune-config.py <autogenerated.yml> <config.yml>
"""

import json
import sys
from pathlib import Path

from ruamel.yaml import YAML

# omp's own state; it stays in config.yml even when the repo sets the same value.
KEEP = {"setupVersion"}


def to_json(value):
    """Type-strict, order-insensitive rendering: unlike `==`, true != 1 and 1 != 1.0."""
    return json.dumps(value, sort_keys=True, default=str)


def prune(live, generated, removed, differing, prefix=""):
    """Delete entries of `live` equal to `generated`; collect removed and differing paths."""
    for key in list(live):
        path = f"{prefix}{key}"
        if key not in generated or path in KEEP:
            continue

        value, managed = live[key], generated[key]
        if isinstance(value, dict) and isinstance(managed, dict) and value:
            prune(value, managed, removed, differing, f"{path}.")
            if not value:
                del live[key]
        elif to_json(value) == to_json(managed):
            del live[key]
            removed.append(path)
        else:
            differing.append((path, managed, value))


def main(generated_path, live_path):
    live_path = Path(live_path)
    if not live_path.exists():
        return

    # Round-trip mode preserves comments, quoting, and unquoted on/off scalars.
    yaml = YAML()
    yaml.preserve_quotes = True
    live = yaml.load(live_path)
    if not isinstance(live, dict):
        return

    removed, differing = [], []
    prune(live, YAML(typ="safe").load(Path(generated_path)), removed, differing)

    if removed:
        yaml.dump(live, live_path)
        print(f"omp: dropped from {live_path} (already in autogenerated.yml):")
        for path in removed:
            print(f"  - {path}")

    if differing:
        print(f"omp: not dropping from {live_path} because they have a different value:")
        for path, managed, value in differing:
            print(f"  - {path}: {to_json(managed)} (autogenerated.yml) vs {to_json(value)} (config.yml)")


if __name__ == "__main__":
    main(*sys.argv[1:])
